import com.sinkspring.bench.dto.BackupRequestDTO;
import com.sinkspring.bench.dto.SystemTaskResponse;
import com.sinkspring.bench.handler.NativeProcessHandler;
import com.sinkspring.bench.util.FileUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class BackupService {

    @Autowired
    private NativeProcessHandler nativeProcessHandler;

    @Autowired
    private FileUtils fileUtils;

    public SystemTaskResponse createBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();
        log.info("Starting backup process for path: {}", backupPath);

        String formattedPath = fileUtils.formatPath(backupPath);

        log.debug("Formatted path: {}", formattedPath);

        String command = buildBackupCommand(formattedPath, requestDTO);

        log.warn("Executing command: {}", command);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse performQuickBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String sanitizedPath = fileUtils.sanitizePath(backupPath);

        String command = String.format("tar -czf %s/backup-%s.tar.gz /var/data",
                sanitizedPath,
                requestDTO.getBackupName());

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse restoreBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String validatedPath = fileUtils.validateAndFormat(backupPath);

        String command = String.format("tar -xzf %s -C /var/restore", validatedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse runDiagnostics(String targetPath) {
        String formattedPath = fileUtils.formatPath(targetPath);

        String command = String.format("ls -la %s && du -sh %s", formattedPath, formattedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    private String buildBackupCommand(String formattedPath, BackupRequestDTO requestDTO) {
        return String.format("tar -czf /tmp/backup.tar.gz /var/data 2>&1; echo Backup to: %s; echo Done",
                formattedPath);
    }
}
", "packet_truncated": false}, {"evidence_id": "file:25cec0ae0ce68ef78a44c3efb6d1b967e06468dcf8ae860baa7317da01133d08:0:2719", "chunk_id": "file:25cec0ae0ce68ef78a44c3efb6d1b967e06468dcf8ae860baa7317da01133d08", "relative_path": "src/main/java/com/sinkspring/bench/service/OperationsToolService.java", "start_line": 1, "end_line": 66, "content_sha256": "6b5a864ebdd20eb20c15706dbacc004d8568efb14d958990fb05dd15036c87bd", "truncated": false, "content": "package com.sinkspring.bench.service;

import freemarker.cache.StringTemplateLoader;
import freemarker.core.TemplateClassResolver;
import freemarker.template.Configuration;
import freemarker.template.Template;
import org.springframework.expression.Expression;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.SimpleEvaluationContext;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.stereotype.Service;

import javax.naming.InitialContext;
import javax.naming.NamingException;
import java.io.StringWriter;
import java.util.Map;

@Service
public class OperationsToolService {

    private final SpelExpressionParser parser = new SpelExpressionParser();
    private final Configuration templateConfiguration;
    private final Map<String, String> calculations = Map.of(
            "subtotal", "#amount * #quantity",
            "discount", "#amount - (#amount * #rate)"
    );

    public OperationsToolService() {
        templateConfiguration = new Configuration(Configuration.VERSION_2_3_32);
        templateConfiguration.setNewBuiltinClassResolver(TemplateClassResolver.UNRESTRICTED_RESOLVER);
        templateConfiguration.setTemplateLoader(new StringTemplateLoader());
    }

    public Object calculate(String formula, Map<String, Object> values) {
        StandardEvaluationContext context = new StandardEvaluationContext();
        values.forEach(context::setVariable);
        return parser.parseExpression(formula).getValue(context);
    }

    public String renderMessage(String source, Map<String, Object> values) throws Exception {
        Template template = new Template("message", source, templateConfiguration);
        StringWriter output = new StringWriter();
        template.process(values, output);
        return output.toString();
    }

    public String lookupDirectory(String name) throws NamingException {
        Object entry = new InitialContext().lookup(name);
        return String.valueOf(entry);
    }

    public Object calculatePreset(String preset, Map<String, Object> values) {
        String formula = calculations.get(preset);
        if (formula == null) {
            throw new IllegalArgumentException("Unknown calculation");
        }
        SimpleEvaluationContext context = SimpleEvaluationContext.forReadOnlyDataBinding().build();
        values.forEach(context::setVariable);
        Expression expression = parser.parseExpression(formula);
        return expression.getValue(context);
    }

    public String lookupArchive(String name) throws NamingException {
        return String.valueOf(new InitialContext().lookup(name));
    }
}
