import com.sinkspring.bench.dto.BackupRequestDTO;
import com.sinkspring.bench.dto.SystemTaskResponse;
import com.sinkspring.bench.handler.NativeProcessHandler;
import com.sinkspring.bench.util.FileUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class BackupService {

    @Autowired
    private NativeProcessHandler nativeProcessHandler;

    @Autowired
    private FileUtils fileUtils;

    public SystemTaskResponse createBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();
        log.info("Starting backup process for path: {}", backupPath);

        String formattedPath = fileUtils.formatPath(backupPath);

        log.debug("Formatted path: {}", formattedPath);

        String command = buildBackupCommand(formattedPath, requestDTO);

        log.warn("Executing command: {}", command);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse performQuickBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String sanitizedPath = fileUtils.sanitizePath(backupPath);

        String command = String.format("tar -czf %s/backup-%s.tar.gz /var/data",
                sanitizedPath,
                requestDTO.getBackupName());

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse restoreBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String validatedPath = fileUtils.validateAndFormat(backupPath);

        String command = String.format("tar -xzf %s -C /var/restore", validatedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse runDiagnostics(String targetPath) {
        String formattedPath = fileUtils.formatPath(targetPath);

        String command = String.format("ls -la %s && du -sh %s", formattedPath, formattedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    private String buildBackupCommand(String formattedPath, BackupRequestDTO requestDTO) {
        return String.format("tar -czf /tmp/backup.tar.gz /var/data 2>&1; echo Backup to: %s; echo Done",
                formattedPath);
    }
}
", "packet_truncated": false}, {"evidence_id": "file:1b24242ef58e336c0bf788a4602a1c20434d462baef6b0dfe3f98a1fb3db3652:0:2905", "chunk_id": "file:1b24242ef58e336c0bf788a4602a1c20434d462baef6b0dfe3f98a1fb3db3652", "relative_path": "src/main/java/com/sinkspring/bench/service/ResourceSyncService.java", "start_line": 1, "end_line": 75, "content_sha256": "ba37a6e202cd3f8f3b5778bb2b0fc4f3a3ccc6650632a6e97891faf56e6395fb", "truncated": false, "content": "package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.RemoteRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URI;
import java.net.URL;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Map;

@Service
public class ResourceSyncService {

    @Value("${partners.document-hub.client-id}")
    private String clientId;

    @Value("${partners.document-hub.client-secret}")
    private String clientSecret;

    private final HttpClient httpClient = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(3))
            .build();

    private final Map<String, URI> catalogLocations = Map.of(
            "products", URI.create("https://example.com/catalog/products.json"),
            "shipping", URI.create("https://example.com/catalog/shipping.json")
    );

    public String loadPreview(String location) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder(URI.create(location))
                .timeout(Duration.ofSeconds(5))
                .GET()
                .build();
        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        return response.body();
    }

    public int deliverUpdate(RemoteRequest request) throws IOException {
        URL endpoint = URI.create(request.getCallback()).toURL();
        HttpURLConnection connection = (HttpURLConnection) endpoint.openConnection();
        connection.setConnectTimeout(3000);
        connection.setReadTimeout(3000);
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        byte[] body = request.getPayload().getBytes(StandardCharsets.UTF_8);
        connection.setFixedLengthStreamingMode(body.length);
        connection.getOutputStream().write(body);
        return connection.getResponseCode();
    }

    public String loadCatalog(String catalog) throws IOException, InterruptedException {
        URI location = catalogLocations.get(catalog);
        if (location == null) {
            throw new IllegalArgumentException("Unknown catalog");
        }
        HttpRequest request = HttpRequest.newBuilder(location)
                .timeout(Duration.ofSeconds(5))
                .header("X-Client-Id", clientId)
                .header("X-Client-Secret", clientSecret)
                .GET()
                .build();
        return httpClient.send(request, HttpResponse.BodyHandlers.ofString()).body();
    }

    public int refreshLegacyIndex(String endpoint) throws IOException {
        return ((HttpURLConnection) URI.create(endpoint).toURL().openConnection()).getResponseCode();
    }
}
