{"investigation_id": "investigation-20", "question": "若renderPage回显save接口存储的未净化内容，与POST /api/pages形成存储型XSS链", "entry": "GET /api/pages/{pageId}（produces text/html），写入入口POST /api/pages", "asset": "renderPage中page.get("TITLE")/page.get("BODY")拼入text/html响应体", "evidence": {"file:511a57ca7fff609259fce5bc50234ff46602a85deb375d3ac80cd56a861fc73e:0:1578": {"chunk_id": "file:511a57ca7fff609259fce5bc50234ff46602a85deb375d3ac80cd56a861fc73e", "evidence_id": "file:511a57ca7fff609259fce5bc50234ff46602a85deb375d3ac80cd56a861fc73e:0:1578", "repository_id": "sinkspring-bench-opt-20260909", "snapshot_id": "sinkspring-bench-opt-20260909-v1", "source_snapshot_id": "e81aeec584964d2fa4ac1ce230c9af32", "index_run_id": "31b18776-3829-424b-a6f8-4642bd0d6ccc", "relative_path": "src/main/java/com/sinkspring/bench/controller/PageController.java", "content": "package com.sinkspring.bench.controller;

import com.sinkspring.bench.dto.PageRequest;
import com.sinkspring.bench.service.PageService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
@RequestMapping("/api/pages")
public class PageController {

    @Autowired
    private PageService pageService;

    @GetMapping(value = "/search", produces = MediaType.TEXT_HTML_VALUE)
    public String search(@RequestParam String query) {
        return pageService.buildSearchPage(query);
    }

    @PostMapping
    public Map<String, String> save(@RequestBody PageRequest request) {
        pageService.savePage(request);
        return Map.of("pageId", request.getPageId());
    }

    @GetMapping(value = "/{pageId}", produces = MediaType.TEXT_HTML_VALUE)
    public String page(@PathVariable String pageId) {
        return pageService.renderPage(pageId);
    }

    @GetMapping(value = "/search/text", produces = MediaType.TEXT_PLAIN_VALUE)
    public String searchText(@RequestParam String query) {
        return pageService.buildSearchText(query);
    }
}
