{"investigation_id": "investigation-30", "question": "若verifySession允许none算法、算法混淆或密钥弱，攻击者可伪造role声明", "entry": "SessionController.details", "asset": "role声明解码返回", "evidence": {"file:16cfbe77c79c17a617a041d61be1ee858982b0d7e8c3d9b7fda84838a6272000:0:1306": {"chunk_id": "file:16cfbe77c79c17a617a041d61be1ee858982b0d7e8c3d9b7fda84838a6272000", "evidence_id": "file:16cfbe77c79c17a617a041d61be1ee858982b0d7e8c3d9b7fda84838a6272000:0:1306", "repository_id": "sinkspring-bench-opt-20260909", "snapshot_id": "sinkspring-bench-opt-20260909-v1", "source_snapshot_id": "e81aeec584964d2fa4ac1ce230c9af32", "index_run_id": "31b18776-3829-424b-a6f8-4642bd0d6ccc", "relative_path": "src/main/java/com/sinkspring/bench/controller/SessionController.java", "content": "package com.sinkspring.bench.controller;

import com.auth0.jwt.interfaces.DecodedJWT;
