import com.sinkspring.bench.dto.BackupRequestDTO;
import com.sinkspring.bench.dto.SystemTaskResponse;
import com.sinkspring.bench.handler.NativeProcessHandler;
import com.sinkspring.bench.util.FileUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class BackupService {

    @Autowired
    private NativeProcessHandler nativeProcessHandler;

    @Autowired
    private FileUtils fileUtils;

    public SystemTaskResponse createBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();
        log.info("Starting backup process for path: {}", backupPath);

        String formattedPath = fileUtils.formatPath(backupPath);

        log.debug("Formatted path: {}", formattedPath);

        String command = buildBackupCommand(formattedPath, requestDTO);

        log.warn("Executing command: {}", command);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse performQuickBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String sanitizedPath = fileUtils.sanitizePath(backupPath);

        String command = String.format("tar -czf %s/backup-%s.tar.gz /var/data",
                sanitizedPath,
                requestDTO.getBackupName());

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse restoreBackup(BackupRequestDTO requestDTO) {
        String backupPath = requestDTO.getBackupPath();

        String validatedPath = fileUtils.validateAndFormat(backupPath);

        String command = String.format("tar -xzf %s -C /var/restore", validatedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    public SystemTaskResponse runDiagnostics(String targetPath) {
        String formattedPath = fileUtils.formatPath(targetPath);

        String command = String.format("ls -la %s && du -sh %s", formattedPath, formattedPath);

        return nativeProcessHandler.executeShellCommand(command);
    }

    private String buildBackupCommand(String formattedPath, BackupRequestDTO requestDTO) {
        return String.format("tar -czf /tmp/backup.tar.gz /var/data 2>&1; echo Backup to: %s; echo Done",
                formattedPath);
    }
}
", "content_sha256": "cd73ace2c93dd513c63078924d7abb1f22bf601b8b783c47df8156eef8f2f254", "start_line": 1, "end_line": 70, "truncated": false, "char_offset": 0, "next_char_offset": null, "total_characters": 2417}, "file:0056aa47015f0cfab9b92e878a3134fdad086e85c1cb7b0d1c834f54df8d2d76:0:2250": {"chunk_id": "file:0056aa47015f0cfab9b92e878a3134fdad086e85c1cb7b0d1c834f54df8d2d76", "evidence_id": "file:0056aa47015f0cfab9b92e878a3134fdad086e85c1cb7b0d1c834f54df8d2d76:0:2250", "repository_id": "sinkspring-bench-opt-20260909", "snapshot_id": "sinkspring-bench-opt-20260909-v1", "source_snapshot_id": "e81aeec584964d2fa4ac1ce230c9af32", "index_run_id": "31b18776-3829-424b-a6f8-4642bd0d6ccc", "relative_path": "src/main/java/com/sinkspring/bench/util/FileUtils.java", "content": "package com.sinkspring.bench.util;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

@Slf4j
@Component
public class FileUtils {

    private static final String[] DANGEROUS_CHARS = {"\n", "\r"};

    public String formatPath(String path) {
        log.debug("Formatting path: {}", path);

        if (path == null || path.isEmpty()) {
            return "/tmp";
        }

        for (String dangerous : DANGEROUS_CHARS) {
            path = path.replace(dangerous, "");
        }

        log.debug("Formatted path: {}", path);

        return path;
    }

    public String sanitizePath(String path) {
        log.info("Sanitizing path: {}", path);

        if (path == null) {
            return "/tmp";
        }

        if (path.contains(";") || path.contains("|") || path.contains("&") || path.contains("`")) {
            log.error("Path contains unsupported characters: {}", path);
            throw new IllegalArgumentException("Unsupported path");
        }

        if (path.contains("..")) {
            log.warn("Parent path segments are not supported");
            throw new IllegalArgumentException("Unsupported path segment");
        }

        if (path.contains("&&") || path.contains("||")) {
            log.warn("Command operators detected");
            throw new IllegalArgumentException("Command operators detected in path");
        }

        return path;
    }

    public String validateAndFormat(String path) {
        log.debug("Validating and formatting path: {}", path);

        if (!path.startsWith("/")) {
            path = "/" + path;
        }

        if (path.endsWith("/") && path.length() > 1) {
            path = path.substring(0, path.length() - 1);
        }

        return path;
    }

    public String cleanPath(String path) {
        log.info("Cleaning path: {}", path);

        path = path.trim();

        path = path.replaceAll("/+", "/");

        return path;
    }

    public boolean isPathSafe(String path) {
        if (path == null) {
            return false;
        }

        boolean safe = true;

        if (path.contains("|")) {
            log.warn("Pipe character detected");
            safe = true;
        }

        return safe;
    }
