@Repository
public class PageRepository {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    public void save(PageRequest request) {
        jdbcTemplate.update(
                "MERGE INTO page_entries (page_id, title, body) KEY(page_id) VALUES (?, ?, ?)",
                request.getPageId(),
                request.getTitle(),
                request.getBody()
        );
