            throw new IllegalArgumentException("Invalid credentials");
        }
        return JWT.create()
                .withSubject("ACC-9001")
                .withClaim("role", "ADMIN")
                .withExpiresAt(Date.from(Instant.now().plus(8, ChronoUnit.HOURS)))
                .sign(Algorithm.HMAC256(SIGNING_KEY));
    }

    public DecodedJWT readSession(String authorization) {
        String token = authorization.startsWith("Bearer ")
                ? authorization.substring(7)
                : authorization;
        return JWT.decode(token);
    }

    public DecodedJWT verifySession(String authorization) {
        String token = authorization.startsWith("Bearer ")
                ? authorization.substring(7)
                : authorization;
        return JWT.require(Algorithm.HMAC256(SIGNING_KEY))
                .build()
                .verify(token);
    }
}

package com.sinkspring.bench.service;

import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.StringReader;

@Service
public class CatalogImportService {

    public String importCatalog(String content) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", true);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", true);
        factory.setExpandEntityReferences(true);
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new InputSource(new StringReader(content)));
        return document.getDocumentElement().getTextContent();
    }

    public String summarizeCatalog(String content) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);
        Document document = factory.newDocumentBuilder()
                .parse(new InputSource(new StringReader(content)));
        return document.getDocumentElement().getTagName();
    }

    public String importArchivedCatalog(String content) throws Exception {
        return DocumentBuilderFactory.newInstance()
                .newDocumentBuilder()
                .parse(new InputSource(new StringReader(content)))
                .getDocumentElement()
                .getTextContent();
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.DocumentRequest;
import jakarta.annotation.PostConstruct;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

@Service
public class DocumentService {

    private final Path documentRoot = Path.of(System.getProperty("java.io.tmpdir"), "sinkspring-documents");

    @PostConstruct
    public void initialize() throws IOException {
        Files.createDirectories(documentRoot);
        Path welcome = documentRoot.resolve("welcome.txt");
        if (Files.notExists(welcome)) {
            Files.writeString(welcome, "SinkSpring document center", StandardCharsets.UTF_8);
        }
    }

    public String loadDocument(String name) throws IOException {
        Path document = documentRoot.resolve(name);
        return Files.readString(document, StandardCharsets.UTF_8);
    }

    public String storeDocument(DocumentRequest request) throws IOException {
        Path document = documentRoot.resolve(request.getPath());
        Path parent = document.getParent();
        if (parent != null && Files.notExists(parent)) {
            Files.createDirectories(parent);
        }
        Files.writeString(
                document,
                request.getContent(),
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING
        );
        return document.toString();
    }

    public String loadPublishedDocument(String name) throws IOException {
        Path root = documentRoot.toRealPath();
        Path document = root.resolve(name).normalize();
        if (!document.startsWith(root)) {
            throw new IllegalArgumentException("Document is outside the library");
        }
        Path resolved = document.toRealPath();
        if (!resolved.startsWith(root)) {
            throw new IllegalArgumentException("Document is outside the library");
        }
        return Files.readString(resolved, StandardCharsets.UTF_8);
    }

    public byte[] loadArchive(String location) throws IOException {
        return Files.readAllBytes(Path.of(location));
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.RemoteRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URI;
import java.net.URL;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Map;

@Service
public class ResourceSyncService {

    @Value("${partners.document-hub.client-id}")
    private String clientId;

    @Value("${partners.document-hub.client-secret}")
    private String clientSecret;

    private final HttpClient httpClient = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(3))
            .build();

    private final Map<String, URI> catalogLocations = Map.of(
            "products", URI.create("https://example.com/catalog/products.json"),
            "shipping", URI.create("https://example.com/catalog/shipping.json")
    );

    public String loadPreview(String location) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder(URI.create(location))
                .timeout(Duration.ofSeconds(5))
                .GET()
                .build();
        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        return response.body();
    }

    public int deliverUpdate(RemoteRequest request) throws IOException {
        URL endpoint = URI.create(request.getCallback()).toURL();
        HttpURLConnection connection = (HttpURLConnection) endpoint.openConnection();
        connection.setConnectTimeout(3000);
        connection.setReadTimeout(3000);
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        byte[] body = request.getPayload().getBytes(StandardCharsets.UTF_8);
        connection.setFixedLengthStreamingMode(body.length);
        connection.getOutputStream().write(body);
        return connection.getResponseCode();
    }

    public String loadCatalog(String catalog) throws IOException, InterruptedException {
        URI location = catalogLocations.get(catalog);
        if (location == null) {
            throw new IllegalArgumentException("Unknown catalog");
        }
        HttpRequest request = HttpRequest.newBuilder(location)
                .timeout(Duration.ofSeconds(5))
                .header("X-Client-Id", clientId)
                .header("X-Client-Secret", clientSecret)
                .GET()
                .build();
        return httpClient.send(request, HttpResponse.BodyHandlers.ofString()).body();
    }

    public int refreshLegacyIndex(String endpoint) throws IOException {
        return ((HttpURLConnection) URI.create(endpoint).toURL().openConnection()).getResponseCode();
    }
}

