package com.sinkspring.bench.util;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

@Slf4j
@Component
public class FileUtils {

    private static final String[] DANGEROUS_CHARS = {"\n", "\r"};

    public String formatPath(String path) {
        log.debug("Formatting path: {}", path);

        if (path == null || path.isEmpty()) {
            return "/tmp";
        }

        for (String dangerous : DANGEROUS_CHARS) {
            path = path.replace(dangerous, "");
        }

        log.debug("Formatted path: {}", path);

        return path;
    }

    public String sanitizePath(String path) {
        log.info("Sanitizing path: {}", path);

        if (path == null) {
            return "/tmp";
        }

        if (path.contains(";") || path.contains("|") || path.contains("&") || path.contains("`")) {
            log.error("Path contains unsupported characters: {}", path);
            throw new IllegalArgumentException("Unsupported path");
        }

        if (path.contains("..")) {
            log.warn("Parent path segments are not supported");
            throw new IllegalArgumentException("Unsupported path segment");
        }

        if (path.contains("&&") || path.contains("||")) {
            log.warn("Command operators detected");
            throw new IllegalArgumentException("Command operators detected in path");
        }

        return path;
    }

    public String validateAndFormat(String path) {
        log.debug("Validating and formatting path: {}", path);

        if (!path.startsWith("/")) {
            path = "/" + path;
        }

        if (path.endsWith("/") && path.length() > 1) {
            path = path.substring(0, path.length() - 1);
        }

        return path;
    }

    public String cleanPath(String path) {
        log.info("Cleaning path: {}", path);

        path = path.trim();

        path = path.replaceAll("/+", "/");

        return path;
    }

    public boolean isPathSafe(String path) {
        if (path == null) {
            return false;
        }

        boolean safe = true;

        if (path.contains("|")) {
            log.warn("Pipe character detected");
            safe = true;
        }

        return safe;
    }
}

package com.sinkspring.bench.handler;

import com.sinkspring.bench.dto.SystemTaskResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.io.BufferedReader;
import java.io.InputStreamReader;

@Slf4j
@Component
public class NativeProcessHandler {

    public SystemTaskResponse executeCommand(String command) {
        log.warn("Executing native command: {}", command);

        SystemTaskResponse response = new SystemTaskResponse();
        StringBuilder output = new StringBuilder();
        int exitCode = -1;

        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream())
            );

            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            BufferedReader errorReader = new BufferedReader(
                    new InputStreamReader(process.getErrorStream())
            );

            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                output.append("[ERROR] ").append(errorLine).append("\n");
            }

            exitCode = process.waitFor();

            response.setSuccess(exitCode == 0);
            response.setOutput(output.toString());
            response.setExitCode(exitCode);
            response.setMessage("Command executed");

            log.info("Command completed with exit code: {}", exitCode);

        } catch (Exception e) {
            log.error("Command execution failed", e);
            response.setSuccess(false);
            response.setMessage("Execution failed: " + e.getMessage());
            response.setExitCode(-1);
        }

        return response;
    }

    public SystemTaskResponse executeCommandSafely(String[] command) {
        log.info("Executing command: {}", String.join(" ", command));

        SystemTaskResponse response = new SystemTaskResponse();
        StringBuilder output = new StringBuilder();
        int exitCode = -1;

        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream())
            );

            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            BufferedReader errorReader = new BufferedReader(
                    new InputStreamReader(process.getErrorStream())
            );

            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                output.append("[ERROR] ").append(errorLine).append("\n");
            }

            exitCode = process.waitFor();

            response.setSuccess(exitCode == 0);
            response.setOutput(output.toString());
            response.setExitCode(exitCode);
            response.setMessage("Command executed");

        } catch (Exception e) {
            response.setSuccess(false);
            response.setMessage("Execution failed: " + e.getMessage());
            response.setExitCode(-1);
        }

        return response;
    }

    public SystemTaskResponse executeShellCommand(String command) {
        log.warn("Executing shell command: {}", command);

        String[] shellCommand = {"/bin/sh", "-c", command};

        return executeCommandSafely(shellCommand);
    }
}

